// api/agenda.js  (Lia: agenda del titolare)
// Un solo file: serve sia la pagina (HTML) sia i dati (JSON).
// Link di accesso: https://TUO-SITO.vercel.app/api/agenda?t=CODICE_SEGRETO
// Variabili su Vercel: SUPABASE_URL, SUPABASE_SECRET_KEY.

const PAGE = "<!doctype html>\n<html lang=\"it\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"color-scheme\" content=\"dark\">\n<title>Il tuo calendario – Lia</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#050608; --bg2:#0A0D12; --card:#0E131B; --card2:#161D29; --line:#1C2532; --line2:#2A3648;\n  --ink:#F9F6F0; --muted:#9BA6B5;\n  --accent:#2DD2DC; --on-accent:#031016; --accent-soft:#0B2C33; --accent-ink:#A5EDF2;\n  --sec:#8CC6FF; --sec-soft:#0A2547; --ter:#EFE9DC; --ter-soft:#2A2720; --danger:#FF8A8A;\n  color-scheme:dark;\n  box-sizing:border-box;\n  padding-top:env(safe-area-inset-top,0px);\n  padding-bottom:env(safe-area-inset-bottom,0px);\n}\n:root{--logo:url(\"data:image/png;base64,\");}\nhtml{background:var(--bg);scroll-padding-top:16px;}\n*{box-sizing:border-box;}\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,\"SF Pro Display\",\"SF Pro Text\",\"Inter\",\"Helvetica Neue\",Helvetica,Arial,sans-serif;font-size:16px;line-height:1.45;-webkit-font-smoothing:antialiased;}\nh1,h2,h3,p{margin:0;}\nbutton{font-family:inherit;}\n:focus-visible{outline:3px solid var(--accent);outline-offset:2px;border-radius:8px;}\n.logo{display:block;width:40px;height:29px;background:var(--logo) center / contain no-repeat;}\n\n/* barra in alto */\n.top{position:sticky;top:0;z-index:20;background:color-mix(in srgb,var(--bg) 86%,transparent);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);border-bottom:1px solid var(--line);padding-top:env(safe-area-inset-top,0px);}\n.top-row{max-width:1100px;margin:0 auto;padding:12px 20px;display:flex;align-items:center;gap:14px;}\n.biz{font-weight:600;font-size:1rem;letter-spacing:-0.01em;}\n.biz small{display:block;color:var(--muted);font-weight:500;font-size:.8rem;}\n.spacer{flex:1;}\n.iconbtn{width:40px;height:40px;border-radius:12px;border:1px solid var(--line2);background:var(--card);color:var(--ink);display:grid;place-items:center;cursor:pointer;}\n.iconbtn:hover{border-color:var(--muted);}\n\n/* controlli */\n.controls{max-width:1100px;margin:0 auto;padding:16px 20px 0;display:flex;flex-wrap:wrap;align-items:center;gap:12px;}\n.seg{display:inline-flex;padding:3px;border-radius:12px;background:var(--card);border:1px solid var(--line);}\n.seg button{min-height:40px;padding:0 16px;border:0;border-radius:9px;background:transparent;color:var(--muted);font-size:.92rem;font-weight:600;cursor:pointer;}\n.seg button[aria-pressed=\"true\"]{background:var(--accent);color:var(--on-accent);}\n.nowbtn{min-height:40px;padding:0 16px;border-radius:12px;border:1px solid var(--line2);background:var(--card);color:var(--ink);font-size:.92rem;font-weight:600;cursor:pointer;}\n.nowbtn:hover{border-color:var(--muted);}\n.arrow{width:40px;height:40px;border-radius:12px;border:1px solid var(--line2);background:var(--card);color:var(--ink);display:grid;place-items:center;cursor:pointer;}\n.arrow:hover{border-color:var(--muted);}\n.range{font-weight:600;font-size:1.05rem;letter-spacing:-0.015em;text-transform:capitalize;min-width:0;}\n.legend{display:flex;flex-wrap:wrap;gap:14px;margin-left:auto;}\n.legend span{display:inline-flex;align-items:center;gap:7px;font-size:.85rem;color:var(--muted);}\n.legend i{width:9px;height:9px;border-radius:50%;display:inline-block;}\n\n/* zona calendario */\n.cal-wrap{max-width:1100px;margin:0 auto;padding:18px 20px 120px;}\n.cal-card{background:var(--card);border:1px solid var(--line);border-radius:28px;overflow:hidden;}\n.grid-scroll{overflow-x:auto;-webkit-overflow-scrolling:touch;}\n.grid{position:relative;display:grid;}\n.grid.week{grid-template-columns:52px repeat(7,minmax(120px,1fr));min-width:920px;}\n.grid.day{grid-template-columns:52px minmax(240px,1fr);min-width:0;}\n.head-row{display:contents;}\n.hcell{position:sticky;top:0;z-index:2;background:var(--card);padding:14px 8px;text-align:center;border-bottom:1px solid var(--line);font-weight:600;font-size:.86rem;}\n.hcell small{display:block;color:var(--muted);font-weight:500;margin-top:2px;}\n.hcell.today{color:var(--accent);}\n.hcell.today small{color:var(--accent-ink);}\n.corner{position:sticky;top:0;left:0;z-index:3;background:var(--card);border-bottom:1px solid var(--line);}\n.timecol{position:relative;}\n.tl{position:absolute;right:8px;transform:translateY(-8px);font-size:.72rem;color:var(--muted);}\n.daycol{position:relative;border-left:1px solid var(--line);background-image:linear-gradient(var(--line) 1px,transparent 1px);}\n.daycol.today{background-color:color-mix(in srgb,var(--accent) 6%,transparent);}\n.nowline{position:absolute;left:0;right:0;height:2px;background:var(--accent);z-index:1;}\n.nowline::before{content:\"\";position:absolute;left:-4px;top:-3px;width:8px;height:8px;border-radius:50%;background:var(--accent);}\n.slot{position:absolute;left:4px;right:4px;border-radius:10px;padding:6px 9px;overflow:hidden;cursor:pointer;border:none;text-align:left;font-family:inherit;color:inherit;}\n.slot:hover{filter:brightness(1.12);}\n.slot b{display:block;font-size:.84rem;font-weight:600;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.slot span{display:block;font-size:.76rem;opacity:.85;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.slot.short span{display:none;}\n.slot.cancelled{opacity:.5;text-decoration:line-through;}\n.slot.a{background:var(--accent-soft);color:var(--accent-ink);box-shadow:inset 3px 0 0 var(--accent);}\n.slot.s{background:var(--sec-soft);color:var(--sec);box-shadow:inset 3px 0 0 var(--sec);}\n.slot.t{background:var(--ter-soft);color:var(--ter);box-shadow:inset 3px 0 0 var(--ter);}\n.empty{padding:64px 24px;text-align:center;color:var(--muted);}\n\n/* vista giornaliera: agenda */\n.agenda{padding:20px;}\n.ag-summary{display:flex;align-items:baseline;gap:12px;flex-wrap:wrap;padding:4px 4px 22px;border-bottom:1px solid var(--line);margin-bottom:22px;}\n.ag-summary .big{font-size:2.2rem;font-weight:700;letter-spacing:-0.04em;}\n.ag-summary .lbl{color:var(--muted);font-size:.95rem;}\n.ag-summary .next{margin-left:auto;font-size:.9rem;color:var(--accent-ink);background:var(--accent-soft);padding:6px 14px;border-radius:999px;font-weight:600;}\n.ag-list{display:grid;gap:12px;}\n.ag-card{display:flex;align-items:stretch;gap:16px;padding:16px 18px;border-radius:20px;background:var(--card2);border:1px solid var(--line);cursor:pointer;text-align:left;font-family:inherit;color:inherit;width:100%;}\n.ag-card:hover{border-color:var(--line2);}\n.ag-card.cancelled{opacity:.5;}\n.ag-card .bar{width:4px;border-radius:2px;flex:none;}\n.ag-card.a .bar{background:var(--accent);} .ag-card.s .bar{background:var(--sec);} .ag-card.t .bar{background:var(--ter);}\n.ag-time{flex:none;width:64px;display:flex;flex-direction:column;justify-content:center;}\n.ag-time b{font-size:1.05rem;font-weight:700;letter-spacing:-0.02em;}\n.ag-time span{font-size:.78rem;color:var(--muted);}\n.ag-mid{flex:1;min-width:0;display:flex;flex-direction:column;justify-content:center;gap:2px;}\n.ag-mid b{font-size:1.08rem;font-weight:600;letter-spacing:-0.01em;}\n.ag-mid .svc{font-size:.9rem;color:var(--muted);}\n.ag-mid .strike{text-decoration:line-through;}\n.ag-tag{flex:none;align-self:center;font-size:.78rem;font-weight:700;padding:3px 10px;border-radius:999px;}\n.ag-card.a .ag-tag{background:var(--accent-soft);color:var(--accent-ink);}\n.ag-card.s .ag-tag{background:var(--sec-soft);color:var(--sec);}\n.ag-card.t .ag-tag{background:var(--ter-soft);color:var(--ter);}\n.ag-empty{padding:72px 24px;text-align:center;color:var(--muted);display:flex;flex-direction:column;align-items:center;gap:14px;}\n.ag-empty svg{opacity:.5;}\n\n/* pannello appuntamento */\n.sheet-bg{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:30;opacity:0;pointer-events:none;transition:opacity .2s;}\n.sheet-bg.on{opacity:1;pointer-events:auto;}\n.sheet{position:fixed;left:0;right:0;bottom:0;z-index:31;background:var(--card2);border-radius:26px 26px 0 0;padding:8px 22px calc(26px + env(safe-area-inset-bottom,0px));max-width:520px;margin:0 auto;transform:translateY(100%);transition:transform .25s cubic-bezier(.2,.8,.2,1);box-shadow:0 -20px 60px rgba(0,0,0,.4);}\n.sheet.on{transform:translateY(0);}\n.grabber{width:36px;height:4px;border-radius:2px;background:var(--line2);margin:10px auto 18px;}\n.sheet h2{font-size:1.35rem;font-weight:700;letter-spacing:-0.02em;}\n.sheet .when{color:var(--muted);margin-top:4px;font-size:.95rem;}\n.sheet .rows{margin-top:20px;display:grid;gap:14px;}\n.sheet .r{display:flex;align-items:center;gap:12px;font-size:.98rem;}\n.sheet .r svg{flex:none;color:var(--muted);}\n.sheet .r a{color:var(--accent-ink);text-decoration:none;font-weight:600;}\n.sheet .actions{margin-top:24px;display:flex;gap:10px;}\n.sheet .btn{flex:1;min-height:50px;border-radius:14px;border:0;font-weight:600;font-size:.98rem;cursor:pointer;}\n.sheet .btn.danger{background:var(--danger);color:#2A0A0A;}\n.sheet .btn.close{background:var(--line2);color:var(--ink);}\n.confirm{display:none;margin-top:16px;padding:14px 16px;border-radius:16px;background:rgba(255,138,138,.1);border:1px solid var(--danger);}\n.confirm.on{display:block;}\n.confirm p{font-size:.92rem;color:var(--ink);margin-bottom:12px;}\n.confirm .row{display:flex;gap:10px;}\n@media (prefers-reduced-motion: reduce){.sheet,.sheet-bg{transition:none;}}\n</style>\n</head>\n<body>\n\n<header class=\"top\">\n  <div class=\"top-row\">\n    <span class=\"logo\" role=\"img\" aria-label=\"Lia\"></span>\n    <div class=\"biz\">Barbiere Mario<small>Il tuo calendario</small></div>\n    <div class=\"spacer\"></div>\n    <button class=\"iconbtn\" id=\"refresh\" type=\"button\" aria-label=\"Aggiorna\">\n      <svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"23 4 23 10 17 10\"></polyline><path d=\"M20.49 15a9 9 0 1 1-2.12-9.36L23 10\"></path></svg>\n    </button>\n  </div>\n  <div class=\"controls\">\n    <div class=\"seg\" role=\"group\" aria-label=\"Visualizzazione\">\n      <button id=\"view-day\" type=\"button\" aria-pressed=\"false\">Giorno</button>\n      <button id=\"view-week\" type=\"button\" aria-pressed=\"true\">Settimana</button>\n    </div>\n    <button class=\"arrow\" id=\"prev\" type=\"button\" aria-label=\"Periodo precedente\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"15 18 9 12 15 6\"></polyline></svg>\n    </button>\n    <h1 class=\"range\" id=\"range\" aria-live=\"polite\"></h1>\n    <button class=\"arrow\" id=\"next\" type=\"button\" aria-label=\"Periodo successivo\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><polyline points=\"9 18 15 12 9 6\"></polyline></svg>\n    </button>\n    <button class=\"nowbtn\" id=\"today\" type=\"button\">Oggi</button>\n    <div class=\"legend\" id=\"legend\"></div>\n  </div>\n</header>\n\n<div class=\"cal-wrap\">\n  <div class=\"cal-card\" id=\"cal-card\">\n    <div class=\"grid-scroll\" id=\"grid-scroll\">\n      <div class=\"grid\" id=\"grid\"></div>\n    </div>\n    <div class=\"agenda\" id=\"agenda\" hidden></div>\n  </div>\n</div>\n\n<div class=\"sheet-bg\" id=\"sheet-bg\"></div>\n<div class=\"sheet\" id=\"sheet\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"sheet-title\" tabindex=\"-1\">\n  <div class=\"grabber\" aria-hidden=\"true\"></div>\n  <h2 id=\"sheet-title\"></h2>\n  <p class=\"when\" id=\"sheet-when\"></p>\n  <div class=\"rows\" id=\"sheet-rows\"></div>\n  <div class=\"actions\" id=\"sheet-actions\">\n    <button class=\"btn close\" id=\"sheet-close\" type=\"button\">Chiudi</button>\n    <button class=\"btn danger\" id=\"sheet-cancel\" type=\"button\">Annulla appuntamento</button>\n  </div>\n  <div class=\"confirm\" id=\"confirm\">\n    <p>Annullare questo appuntamento? Il cliente non verrà avvisato in automatico.</p>\n    <div class=\"row\">\n      <button class=\"btn close\" id=\"confirm-no\" type=\"button\">No, tieni</button>\n      <button class=\"btn danger\" id=\"confirm-yes\" type=\"button\">Sì, annulla</button>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  var DAY_NAMES = ['Domenica','Lunedì','Martedì','Mercoledì','Giovedì','Venerdì','Sabato'];\n  var DAY_SHORT = ['Dom','Lun','Mar','Mer','Gio','Ven','Sab'];\n  var MONTHS = ['gennaio','febbraio','marzo','aprile','maggio','giugno','luglio','agosto','settembre','ottobre','novembre','dicembre'];\n  var START_HOUR = 8, END_HOUR = 20, PX_PER_HOUR = 64;\n  var COLORS = {a:'Taglio', s:'Barba', t:'Capelli + Barba'};\n\n  var token = new URLSearchParams(location.search).get('t') || '';\n  var PALETTE = ['a', 's', 't'];\n  var serviceColor = {};\n  function colorFor(service){\n    var key = service || '\\u2014';\n    if (!serviceColor[key]) serviceColor[key] = PALETTE[Object.keys(serviceColor).length % PALETTE.length];\n    return serviceColor[key];\n  }\n  function dayKeyLocal(d){ return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0'); }\n  function daysBetween(a, b){ return Math.round((new Date(b.getFullYear(),b.getMonth(),b.getDate()) - new Date(a.getFullYear(),a.getMonth(),a.getDate())) / 86400000); }\n\n  var state = { mode:'week', anchor:startOfWeek(new Date()), events:[], selected:null };\n\n  function startOfWeek(d){\n    var x = new Date(d); var wd = (x.getDay() + 6) % 7;\n    x.setDate(x.getDate() - wd); x.setHours(0,0,0,0); return x;\n  }\n  function sameDay(a,b){ return a.getFullYear()===b.getFullYear() && a.getMonth()===b.getMonth() && a.getDate()===b.getDate(); }\n  function fmtTime(d){ return String(d.getHours()).padStart(2,'0') + ':' + String(d.getMinutes()).padStart(2,'0'); }\n  function fmtDay(d){ return d.getDate() + ' ' + MONTHS[d.getMonth()]; }\n\n  var bizTz = 'Europe/Rome';\n  function showFatalError(msg){\n    document.querySelector('.cal-wrap').innerHTML = '<div style=\"max-width:520px;margin:60px auto;padding:20px;border-radius:16px;border:1px solid var(--danger,#FF8A8A);color:var(--danger,#FF8A8A);text-align:center;\">' + msg + '</div>';\n    document.querySelector('.controls').style.display = 'none';\n  }\n\n  function loadEvents(){\n    if (!token){ showFatalError('Manca il codice nell\\'indirizzo.'); return; }\n    var weekMonday = startOfWeek(state.anchor);\n    var rangeStart = state.mode === 'day' ? new Date(state.anchor.getFullYear(), state.anchor.getMonth(), state.anchor.getDate()) : weekMonday;\n    var days = state.mode === 'day' ? 1 : 7;\n    var today = new Date(); today.setHours(0,0,0,0);\n    var offset = Math.max(daysBetween(today, rangeStart), 0);\n\n    fetch('/api/agenda?t=' + encodeURIComponent(token) + '&format=json&offset=' + offset + '&days=' + days)\n      .then(function(r){ return r.json().then(function(d){ return {ok:r.ok, status:r.status, data:d}; }); })\n      .then(function(res){\n        if (res.status === 404){ showFatalError('Questo link non \\u00e8 valido. Chiedi il link giusto a chi gestisce il servizio.'); return; }\n        if (!res.ok){ return; }\n        bizTz = res.data.timezone || bizTz;\n        var bizName = document.querySelector('.biz');\n        if (bizName && bizName.firstChild) bizName.firstChild.textContent = res.data.business;\n        document.title = 'Agenda \\u2013 ' + res.data.business;\n\n        state.events = (res.data.appointments || []).map(function(a){\n          var start = new Date(a.starts_at), end = new Date(a.ends_at);\n          return {\n            id: a.id,\n            day: (start.getDay() + 6) % 7,\n            color: colorFor(a.service),\n            name: a.customer_name,\n            service: a.service || '',\n            phone: a.customer_phone || '',\n            start: start, end: end,\n            cancelled: false\n          };\n        });\n        buildLegend();\n        render();\n      })\n      .catch(function(){ /* mantiene la vista com'era; l'utente pu\\u00f2 premere Aggiorna */ });\n  }\n\n  function rangeLabel(){\n    if (state.mode === 'day'){\n      return DAY_NAMES[state.anchor.getDay()] + ' ' + fmtDay(state.anchor);\n    }\n    var end = new Date(state.anchor); end.setDate(end.getDate() + 6);\n    if (state.anchor.getMonth() === end.getMonth()){\n      return state.anchor.getDate() + '\\u2013' + end.getDate() + ' ' + MONTHS[end.getMonth()];\n    }\n    return fmtDay(state.anchor) + ' \\u2013 ' + fmtDay(end);\n  }\n\n  function buildLegend(){\n    var el = document.getElementById('legend');\n    el.textContent = '';\n    Object.keys(serviceColor).forEach(function(name){\n      var k = serviceColor[name];\n      var s = document.createElement('span');\n      var i = document.createElement('i'); i.className = 'dotcolor'; i.style.background = 'var(--' + ({a:'accent',s:'sec',t:'ter'})[k] + ')';\n      s.appendChild(i); s.appendChild(document.createTextNode(name));\n      el.appendChild(s);\n    });\n  }\n\n  function hourLines(colEl){\n    for (var h = START_HOUR; h <= END_HOUR; h++){\n      var line = document.createElement('div');\n      line.style.position = 'absolute'; line.style.left = '0'; line.style.right = '0';\n      line.style.top = ((h - START_HOUR) * PX_PER_HOUR) + 'px'; line.style.height = '0';\n      colEl.appendChild(line);\n    }\n  }\n\n  function placeNowLine(colEl, day){\n    var now = new Date();\n    if (!sameDay(now, day)) return;\n    var mins = (now.getHours() - START_HOUR) * 60 + now.getMinutes();\n    if (mins < 0 || mins > (END_HOUR - START_HOUR) * 60) return;\n    var line = document.createElement('div');\n    line.className = 'nowline';\n    line.style.top = (mins / 60 * PX_PER_HOUR) + 'px';\n    colEl.appendChild(line);\n  }\n\n  function eventsForDayIndex(idx){\n    return state.events.filter(function(e){ return e.day === idx; }).sort(function(a,b){ return a.start - b.start; });\n  }\n\n  function layoutColumn(colEl, evs){\n    // colonne semplici per sovrapposizioni\n    var sorted = evs.slice().sort(function(a,b){ return a.start - b.start; });\n    var clusters = [];\n    sorted.forEach(function(e){\n      var placed = false;\n      for (var i = 0; i < clusters.length; i++){\n        if (clusters[i].end > e.start){ clusters[i].items.push(e); clusters[i].end = Math.max(clusters[i].end, e.end); placed = true; break; }\n      }\n      if (!placed) clusters.push({end:e.end, items:[e]});\n    });\n    clusters.forEach(function(cl){\n      var cols = [];\n      cl.items.forEach(function(e){\n        var slot = 0;\n        while (cols[slot] && cols[slot] > e.start) slot++;\n        cols[slot] = e.end;\n        e._col = slot;\n      });\n      var total = cols.length;\n      cl.items.forEach(function(e){ e._of = total; });\n    });\n\n    evs.forEach(function(e){\n      var top = ((e.start.getHours() - START_HOUR) * 60 + e.start.getMinutes()) / 60 * PX_PER_HOUR;\n      var dur = (e.end - e.start) / 60000;\n      var height = Math.max(dur / 60 * PX_PER_HOUR - 2, 20);\n      var btn = document.createElement('button');\n      btn.type = 'button';\n      btn.className = 'slot ' + e.color + (height < 34 ? ' short' : '') + (e.cancelled ? ' cancelled' : '');\n      btn.style.top = top + 'px';\n      btn.style.height = height + 'px';\n      var width = 100 / e._of;\n      btn.style.left = 'calc(' + (width * e._col) + '% + 4px)';\n      btn.style.right = 'calc(' + (100 - width * (e._col + 1)) + '% + 4px)';\n      btn.innerHTML = '<b></b><span></span>';\n      btn.querySelector('b').textContent = fmtTime(e.start) + ' ' + e.name;\n      btn.querySelector('span').textContent = e.service;\n      btn.setAttribute('aria-label', e.name + ', ' + e.service + ', ' + fmtTime(e.start) + '\\u2013' + fmtTime(e.end) + (e.cancelled ? ', annullato' : ''));\n      btn.addEventListener('click', function(){ openSheet(e); });\n      colEl.appendChild(btn);\n    });\n  }\n\n  function renderWeekGrid(){\n    var grid = document.getElementById('grid');\n    grid.textContent = '';\n    grid.className = 'grid week';\n\n    var days = [];\n    for (var i = 0; i < 7; i++){ var d = new Date(state.anchor); d.setDate(d.getDate() + i); days.push(d); }\n    var totalHeight = (END_HOUR - START_HOUR) * PX_PER_HOUR;\n\n    var corner = document.createElement('div'); corner.className = 'corner'; grid.appendChild(corner);\n    days.forEach(function(d){\n      var hc = document.createElement('div');\n      hc.className = 'hcell' + (sameDay(d, new Date()) ? ' today' : '');\n      hc.innerHTML = '<span></span><small></small>';\n      hc.querySelector('span').textContent = DAY_SHORT[d.getDay()];\n      hc.querySelector('small').textContent = d.getDate() + ' ' + MONTHS[d.getMonth()].slice(0,3);\n      grid.appendChild(hc);\n    });\n\n    var timecol = document.createElement('div'); timecol.className = 'timecol'; timecol.style.height = totalHeight + 'px';\n    for (var h = START_HOUR; h <= END_HOUR; h++){\n      var lab = document.createElement('div'); lab.className = 'tl';\n      lab.style.top = ((h - START_HOUR) * PX_PER_HOUR) + 'px'; lab.textContent = h + ':00';\n      timecol.appendChild(lab);\n    }\n    grid.appendChild(timecol);\n\n    days.forEach(function(d){\n      var idx = (d.getDay() + 6) % 7;\n      var col = document.createElement('div');\n      col.className = 'daycol' + (sameDay(d, new Date()) ? ' today' : '');\n      col.style.height = totalHeight + 'px';\n      col.style.backgroundSize = '100% ' + PX_PER_HOUR + 'px';\n      hourLines(col);\n      layoutColumn(col, eventsForDayIndex(idx));\n      placeNowLine(col, d);\n      grid.appendChild(col);\n    });\n  }\n\n  function ordinalWord(n){ return n === 1 ? 'appuntamento' : 'appuntamenti'; }\n\n  function renderDayAgenda(){\n    var agenda = document.getElementById('agenda');\n    agenda.textContent = '';\n    var idx = (state.anchor.getDay() + 6) % 7;\n    var evs = eventsForDayIndex(idx);\n    var active = evs.filter(function(e){ return !e.cancelled; });\n\n    var summary = document.createElement('div'); summary.className = 'ag-summary';\n    var big = document.createElement('span'); big.className = 'big'; big.textContent = active.length;\n    var lbl = document.createElement('span'); lbl.className = 'lbl'; lbl.textContent = ordinalWord(active.length) + (sameDay(state.anchor, new Date()) ? ' oggi' : '');\n    summary.appendChild(big); summary.appendChild(lbl);\n\n    var now = new Date();\n    if (sameDay(state.anchor, now)){\n      var upcoming = active.filter(function(e){ return e.end > now; }).sort(function(a,b){ return a.start - b.start; })[0];\n      if (upcoming){\n        var next = document.createElement('span'); next.className = 'next';\n        var mins = Math.round((upcoming.start - now) / 60000);\n        next.textContent = mins > 1 ? 'Il prossimo è ' + upcoming.name + ' tra ' + mins + ' min' :\n                            (mins >= -1 ? upcoming.name + ' è ora' : 'In corso: ' + upcoming.name);\n        summary.appendChild(next);\n      }\n    }\n    agenda.appendChild(summary);\n\n    if (!evs.length){\n      var empty = document.createElement('div'); empty.className = 'ag-empty';\n      empty.innerHTML = '<svg width=\"40\" height=\"40\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"3\"></rect><line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"></line><line x1=\"8\" y1=\"3\" x2=\"8\" y2=\"7\"></line><line x1=\"16\" y1=\"3\" x2=\"16\" y2=\"7\"></line></svg>';\n      var p2 = document.createElement('p'); p2.textContent = 'Nessun appuntamento in questo giorno.';\n      empty.appendChild(p2); agenda.appendChild(empty);\n      return;\n    }\n\n    var list = document.createElement('div'); list.className = 'ag-list';\n    evs.sort(function(a,b){ return a.start - b.start; }).forEach(function(e){\n      var card = document.createElement('button');\n      card.type = 'button';\n      card.className = 'ag-card ' + e.color + (e.cancelled ? ' cancelled' : '');\n      card.setAttribute('aria-label', e.name + ', ' + e.service + ', ' + fmtTime(e.start) + '–' + fmtTime(e.end) + (e.cancelled ? ', annullato' : ''));\n      var bar = document.createElement('span'); bar.className = 'bar';\n      var time = document.createElement('span'); time.className = 'ag-time';\n      time.innerHTML = '<b></b><span></span>'; time.querySelector('b').textContent = fmtTime(e.start); time.querySelector('span').textContent = fmtTime(e.end);\n      var mid = document.createElement('span'); mid.className = 'ag-mid';\n      mid.innerHTML = '<b></b><span class=\"svc\"></span>';\n      mid.querySelector('b').className = e.cancelled ? 'strike' : '';\n      mid.querySelector('b').textContent = e.name;\n      mid.querySelector('.svc').textContent = e.service + (e.cancelled ? ' · Annullato' : '');\n      var tag = document.createElement('span'); tag.className = 'ag-tag'; tag.textContent = e.service || '';\n      card.appendChild(bar); card.appendChild(time); card.appendChild(mid); card.appendChild(tag);\n      card.addEventListener('click', function(){ openSheet(e); });\n      list.appendChild(card);\n    });\n    agenda.appendChild(list);\n  }\n\n  function render(){\n    document.getElementById('range').textContent = rangeLabel();\n    document.getElementById('view-day').setAttribute('aria-pressed', state.mode === 'day' ? 'true' : 'false');\n    document.getElementById('view-week').setAttribute('aria-pressed', state.mode === 'week' ? 'true' : 'false');\n    var today0 = new Date(); today0.setHours(0,0,0,0);\n    var atStart = state.mode === 'day' ? sameDay(state.anchor, today0) : sameDay(startOfWeek(state.anchor), startOfWeek(today0));\n    document.getElementById('prev').disabled = atStart;\n    document.getElementById('prev').style.opacity = atStart ? '.35' : '';\n\n    var gridScroll = document.getElementById('grid-scroll');\n    var agendaEl = document.getElementById('agenda');\n    if (state.mode === 'day'){\n      gridScroll.hidden = true; agendaEl.hidden = false;\n      renderDayAgenda();\n    } else {\n      agendaEl.hidden = true; gridScroll.hidden = false;\n      renderWeekGrid();\n    }\n  }\n\n  // ---- pannello di dettaglio ----\n  var sheetBg = document.getElementById('sheet-bg');\n  var sheet = document.getElementById('sheet');\n  function icon(path){ return '<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">' + path + '</svg>'; }\n  function openSheet(e){\n    state.selected = e;\n    document.getElementById('sheet-title').textContent = e.name;\n    document.getElementById('sheet-when').textContent = DAY_NAMES[e.start.getDay()] + ' ' + fmtDay(e.start) + ' \\u00b7 ' + fmtTime(e.start) + '\\u2013' + fmtTime(e.end);\n    var rows = document.getElementById('sheet-rows');\n    rows.innerHTML =\n      '<div class=\"r\">' + icon('<circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M8 12h8M12 8v8\"></path>') + '<span>' + e.service + '</span></div>' +\n      '<div class=\"r\">' + icon('<path d=\"M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1.9.3 1.8.6 2.7a2 2 0 0 1-.5 2.1L8 9.7a16 16 0 0 0 6 6l1.2-1.2a2 2 0 0 1 2.1-.5c.9.3 1.8.5 2.7.6a2 2 0 0 1 1.7 2z\"></path>') +\n        '<a href=\"tel:' + e.phone.replace(/\\s+/g,'') + '\">' + e.phone + '</a></div>';\n    document.getElementById('confirm').classList.remove('on');\n    document.getElementById('sheet-actions').style.display = 'flex';\n    document.getElementById('sheet-cancel').disabled = e.cancelled;\n    document.getElementById('sheet-cancel').textContent = e.cancelled ? 'Già annullato' : 'Annulla appuntamento';\n    sheetBg.classList.add('on'); sheet.classList.add('on');\n    sheet.focus();\n    document.addEventListener('keydown', onEsc);\n  }\n  function closeSheet(){\n    sheetBg.classList.remove('on'); sheet.classList.remove('on');\n    document.getElementById('confirm').classList.remove('on');\n    document.removeEventListener('keydown', onEsc);\n  }\n  function onEsc(ev){ if (ev.key === 'Escape') closeSheet(); }\n  sheetBg.addEventListener('click', closeSheet);\n  document.getElementById('sheet-close').addEventListener('click', closeSheet);\n  document.getElementById('sheet-cancel').addEventListener('click', function(){ document.getElementById('confirm').classList.add('on'); });\n  document.getElementById('confirm-no').addEventListener('click', function(){ document.getElementById('confirm').classList.remove('on'); });\n  document.getElementById('confirm-yes').addEventListener('click', function(){\n    if (!state.selected) return;\n    var id = state.selected.id;\n    var btn = document.getElementById('confirm-yes');\n    btn.disabled = true; btn.textContent = 'Annullo\\u2026';\n    fetch('/api/agenda?t=' + encodeURIComponent(token), {\n      method: 'POST',\n      headers: {'Content-Type': 'application/json'},\n      body: JSON.stringify({id: id})\n    }).then(function(r){ return r.json().then(function(d){ return {ok:r.ok, data:d}; }); })\n      .then(function(res){\n        btn.disabled = false; btn.textContent = 'S\\u00ec, annulla';\n        closeSheet();\n        if (res.ok) loadEvents();\n      })\n      .catch(function(){\n        btn.disabled = false; btn.textContent = 'S\\u00ec, annulla';\n      });\n  });\n\n  // ---- controlli periodo ----\n  document.getElementById('view-day').addEventListener('click', function(){ state.mode = 'day'; loadEvents(); });\n  document.getElementById('view-week').addEventListener('click', function(){ state.mode = 'week'; state.anchor = startOfWeek(state.anchor); loadEvents(); });\n  document.getElementById('prev').addEventListener('click', function(){\n    if (document.getElementById('prev').disabled) return;\n    state.anchor = new Date(state.anchor); state.anchor.setDate(state.anchor.getDate() - (state.mode === 'day' ? 1 : 7)); loadEvents();\n  });\n  document.getElementById('next').addEventListener('click', function(){\n    state.anchor = new Date(state.anchor); state.anchor.setDate(state.anchor.getDate() + (state.mode === 'day' ? 1 : 7)); loadEvents();\n  });\n  document.getElementById('today').addEventListener('click', function(){\n    state.anchor = state.mode === 'day' ? new Date() : startOfWeek(new Date()); loadEvents();\n  });\n  document.getElementById('refresh').addEventListener('click', loadEvents);\n\n  buildLegend();\n  loadEvents();\n  setInterval(function(){ if (state.mode !== 'day' || sameDay(state.anchor, new Date())) render(); }, 60000);\n})();\n</script>\n</body>\n</html>\n";

function sbHeaders(extra) {
  const key = process.env.SUPABASE_SECRET_KEY || "";
  const h = { apikey: key, "Content-Type": "application/json" };
  if (key.startsWith("eyJ")) h.Authorization = "Bearer " + key;
  return Object.assign(h, extra || {});
}

async function sb(method, path, body, prefer) {
  const res = await fetch(process.env.SUPABASE_URL + "/rest/v1/" + path, {
    method: method,
    headers: sbHeaders(prefer ? { Prefer: prefer } : {}),
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch (e) {
    data = text;
  }
  return { ok: res.ok, status: res.status, data: data };
}

function tzOffsetMs(utcMs, tz) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: tz, hourCycle: "h23",
    year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", second: "2-digit",
  }).formatToParts(new Date(utcMs));
  const get = (t) => Number(parts.find((p) => p.type === t).value);
  return Date.UTC(get("year"), get("month") - 1, get("day"), get("hour"), get("minute"), get("second")) - utcMs;
}

function zonedTimeToUtc(dateStr, timeStr, tz) {
  const [y, m, d] = dateStr.split("-").map(Number);
  const [hh, mm] = timeStr.split(":").map(Number);
  const guess = Date.UTC(y, m - 1, d, hh, mm);
  const off1 = tzOffsetMs(guess, tz);
  let utc = guess - off1;
  const off2 = tzOffsetMs(utc, tz);
  if (off2 !== off1) utc = guess - off2;
  return new Date(utc);
}

function todayStr(tz) {
  return new Intl.DateTimeFormat("en-CA", { timeZone: tz }).format(new Date());
}

function addDays(dateStr, n) {
  const [y, m, d] = dateStr.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
}

async function getBusinessByToken(token) {
  if (!/^[a-f0-9]{32,128}$/.test(token)) return null;
  const r = await sb("GET", "businesses?agenda_token=eq." + token + "&active=eq.true&select=id,name,timezone");
  if (!r.ok || !Array.isArray(r.data) || !r.data.length) return null;
  return r.data[0];
}

module.exports = async (req, res) => {
  res.setHeader("Cache-Control", "no-store");
  res.setHeader("X-Robots-Tag", "noindex");
  res.setHeader("Referrer-Policy", "no-referrer");

  const q = req.query || {};
  const wantsData = req.method === "POST" || q.format === "json";

  // 1) La pagina
  if (!wantsData) {
    res.setHeader("Content-Type", "text/html; charset=utf-8");
    return res.status(200).send(PAGE);
  }

  try {
    // 2) I dati: serve il codice segreto
    const biz = await getBusinessByToken(String(q.t || ""));
    if (!biz) return res.status(404).json({ error: "Link non valido" });
    const tz = biz.timezone || "Europe/Rome";

    // Annullare un appuntamento
    if (req.method === "POST") {
      const id = String((req.body || {}).id || "");
      if (!/^[0-9a-f-]{36}$/.test(id)) return res.status(400).json({ error: "Richiesta non valida" });
      const r = await sb(
        "PATCH",
        "appointments?id=eq." + id + "&business_id=eq." + biz.id + "&status=eq.confirmed",
        { status: "cancelled" },
        "return=representation"
      );
      if (!r.ok || !Array.isArray(r.data) || !r.data.length) return res.status(404).json({ error: "Appuntamento non trovato" });
      return res.status(200).json({ ok: true });
    }

    // Leggere l'agenda
    const today = todayStr(tz);
    const offset = Math.min(Math.max(parseInt(q.offset || "0", 10) || 0, 0), 60);
    const days = Math.min(Math.max(parseInt(q.days || "1", 10) || 1, 1), 14);
    const date = addDays(today, offset);
    const start = zonedTimeToUtc(date, "00:00", tz);
    const end = zonedTimeToUtc(addDays(date, days), "00:00", tz);

    const r = await sb(
      "GET",
      "appointments?business_id=eq." + biz.id +
        "&status=eq.confirmed" +
        "&starts_at=gte." + encodeURIComponent(start.toISOString()) +
        "&starts_at=lt." + encodeURIComponent(end.toISOString()) +
        "&order=starts_at.asc" +
        "&select=id,starts_at,ends_at,customer_name,customer_phone,customer_address,notes,services(name),resources(name)"
    );
    if (!r.ok || !Array.isArray(r.data)) return res.status(500).json({ error: "Errore nella lettura dell'agenda" });

    return res.status(200).json({
      business: biz.name,
      timezone: tz,
      today: today,
      date: date,
      days: days,
      appointments: r.data.map((a) => ({
        id: a.id,
        starts_at: a.starts_at,
        ends_at: a.ends_at,
        customer_name: a.customer_name,
        customer_phone: a.customer_phone,
        customer_address: a.customer_address,
        notes: a.notes,
        service: a.services ? a.services.name : null,
        resource: a.resources ? a.resources.name : null,
      })),
    });
  } catch (e) {
    console.error(e);
    return res.status(500).json({ error: "Errore" });
  }
};
